command:
// ==========================================
// LUNAS WIRKUNG: MILCH DER REINIGUNG (NURTI)
//
// - Voraussetzung: aktiver Effekt „Nurtis Schale“
// - genau ein Ziel
// - Zielkategorie: Erwachte
// - Empfänger der Milch trägt den Effekt
// - neutralisiert ein Gift bis maximal Giftstufe QS
// - keine automatische Auswahl oder Löschung eines Giftes
// - keine Reichweitenprüfung
// - Dauer: sofortig
// - Erinnerungseffekt bleibt, bis er gelöscht wird
// - gespeichertes Ziel ohne neues GM-Target
// - Effektanlage über Framework
// - Wirkungsende über Framework
// - eine öffentliche Karte + „Effekt anwenden“
// ==========================================

(async function () {
    const macroUuid =
        this?.uuid ||
        game.macros.getName("Milch der Reinigung")?.uuid ||
        null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid =
        "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";

    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden ||
        !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Target?.Merken ||
        !globalThis.DSK?.Target?.Finden ||
        !globalThis.DSK?.Target?.Actor ||
        !globalThis.DSK?.Wesen?.match ||
        !globalThis.DSK?.GMAnfrage?.Speichern ||
        !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen ||
        !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);

        if (!fwMacro?.execute) {
            return ui.notifications.error(
                "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
            );
        }

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden ||
        !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Target?.Merken ||
        !DSK_FW?.Target?.Finden ||
        !DSK_FW?.Target?.Actor ||
        !DSK_FW?.Wesen?.match ||
        !DSK_FW?.GMAnfrage?.Speichern ||
        !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen ||
        !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!"
        );
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Milch der Reinigung";
    const vollerName = "Milch der Reinigung (Nurti)";
    const ahne = "Nurti";

    const flagKey = "pendingMilchDerReinigungNurti";
    const endeKey = "nurtiMilchDerReinigung";

    const dauerText =
        "Sofortig (Erinnerungseffekt bleibt, bis er gelöscht wird)";

    const endeText =
        "Die reinigende Magie der Milch verfliegt.";

    DSK_FW.EffektEnde.Register(
        endeKey,
        vollerName,
        endeText
    );

    // +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (
            actor?.getFlag(
                "world",
                "letzteGabenQS"
            ) !== undefined
        ) {
            await actor.unsetFlag(
                "world",
                "letzteGabenQS"
            );
        }

        if (
            actor?.getFlag(
                "world",
                "letzteGabenMessageId"
            ) !== undefined
        ) {
            await actor.unsetFlag(
                "world",
                "letzteGabenMessageId"
            );
        }
    };

    const hatNurtisSchale = actor =>
        (actor?.effects || []).some(effect =>
            !effect.disabled &&
            (
                effect.getFlag(
                    "dsk",
                    "isNurtisSchale"
                ) === true ||
                String(
                    effect.name ||
                    effect.label ||
                    ""
                )
                    .toLowerCase()
                    .includes("nurtis schale")
            )
        );

    const istErwacht = actor =>
        DSK_FW.Wesen.match(
            actor,
            [
                "erwacht",
                "erwachter",
                "erwachte"
            ]
        );

    const ladeZiel = async daten => {
        if (!daten) {
            return {
                token: null,
                actor: null
            };
        }

        const token =
            await DSK_FW.Target.Finden(daten);

        return {
            token,
            actor:
                token?.actor ||
                await DSK_FW.Target.Actor(daten)
        };
    };

    const findeEigeneEffekte = (
        actor,
        casterUuid
    ) =>
        (actor?.effects || []).filter(effect =>
            (
                effect.name ||
                effect.label ||
                ""
            ) === vollerName &&
            effect.getFlag(
                "dsk",
                "isMilchDerReinigung"
            ) === true &&
            effect.getFlag(
                "dsk",
                "casterUuid"
            ) === casterUuid
        );

    const beschreibungFuer = (
        targetName,
        qs
    ) =>
        `<b>${targetName}</b> trinkt die Milch der Reinigung ` +
        `aus Nurtis geweihter Schale.` +
        `<br><br>Die verzauberte Milch neutralisiert ein Gift ` +
        `im Körper des Empfängers bis zu einer maximalen ` +
        `Giftstufe von <b>${qs}</b>.` +
        `<br><br>Welches Gift neutralisiert wird, bestimmt die Spielleitung.` +
        `<br><b>Zielkategorie:</b> Erwachte`;

    // +++ 4 - EFFEKT AUF EMPFÄNGER ANWENDEN +++++++++++++++++++

    const wendeEffektAn = async ({
        casterActor,
        targetActor,
        qs
    }) => {
        if (
            !casterActor ||
            !targetActor ||
            !istErwacht(targetActor)
        ) {
            return false;
        }

        const alteEffekte =
            findeEigeneEffekte(
                targetActor,
                casterActor.uuid
            );

        if (alteEffekte.length) {
            await targetActor.deleteEmbeddedDocuments(
                "ActiveEffect",
                alteEffekte.map(effect => effect.id)
            );
        }

        const targetName =
            DSK_FW.ResolveTokenName(targetActor) ||
            targetActor.name;

        const effekt =
            await DSK_FW.Effekt.Anwenden({
                name: vollerName,
                ahne,

                beschreibung:
                    `<b>${targetName}</b> hat die Milch der Reinigung getrunken.` +
                    `<br><br>Ein Gift im Körper des Empfängers kann bis zu ` +
                    `einer maximalen Giftstufe von <b>${qs}</b> neutralisiert werden.` +
                    `<br><br>Welches Gift neutralisiert wurde, wird durch die ` +
                    `Spielleitung bestimmt.` +
                    `<br><b>Wirkungsdauer:</b> ${dauerText}`,

                gabeZiel: "erwachte",
                qs,

                // Der Empfänger der Milch trägt den Erinnerungseffekt.
                ziel: targetActor,

                // Die Gabe verändert keinen numerischen Statuswert.
                changes: [],

                showIcon: 1,

                flags: {
                    dsk: {
                        isMilchDerReinigung: true,
                        casterUuid: casterActor.uuid,
                        qs,
                        maximaleGiftstufe: qs,
                        giftNeutralisiert: true,

                        wirkungsende: {
                            sfName: endeKey,
                            basisEffektName: vollerName,
                            beschreibungFuerEnde:
                                endeText
                        }
                    }
                }
            });

        if (!effekt) {
            return false;
        }

        const endeDaten =
            effekt.getFlag(
                "dsk",
                "wirkungsende"
            );

        return Boolean(
            (
                effekt.name ||
                effekt.label ||
                ""
            ) === vollerName &&
            effekt.parent?.uuid ===
                targetActor.uuid &&
            effekt.getFlag(
                "dsk",
                "isMilchDerReinigung"
            ) === true &&
            effekt.getFlag(
                "dsk",
                "casterUuid"
            ) === casterActor.uuid &&
            Number(
                effekt.getFlag(
                    "dsk",
                    "qs"
                )
            ) === qs &&
            Number(
                effekt.getFlag(
                    "dsk",
                    "maximaleGiftstufe"
                )
            ) === qs &&
            effekt.getFlag(
                "dsk",
                "giftNeutralisiert"
            ) === true &&
            endeDaten?.sfName ===
                endeKey &&
            endeDaten?.basisEffektName ===
                vollerName &&
            endeDaten?.beschreibungFuerEnde ===
                endeText
        );
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++

    const verarbeiteAnfrage = async (
        casterActor,
        daten
    ) => {
        if (
            !game.user.isGM ||
            !casterActor ||
            !daten
        ) {
            return false;
        }

        if (
            daten.casterUuid &&
            daten.casterUuid !==
                casterActor.uuid
        ) {
            ui.notifications.warn(
                "Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden."
            );

            return false;
        }

        if (
            daten.sceneId &&
            daten.sceneId !==
                canvas.scene?.id
        ) {
            ui.notifications.warn(
                `Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
            );

            return false;
        }

        const casterToken =
            DSK_FW.Token.Finde(
                casterActor,
                daten.casterTokenId,
                daten.casterTokenUuid
            );

        if (!casterToken) {
            ui.notifications.warn(
                `Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`
            );

            return false;
        }

        const {
            token: targetToken,
            actor: targetActor
        } = await ladeZiel(daten.target);

        const qs = Math.max(
            1,
            Math.floor(
                Number(daten.qs) || 1
            )
        );

        const casterName =
            daten.casterName ||
            DSK_FW.ResolveTokenName(
                casterActor
            );

        const targetName =
            daten.target?.name ||
            targetToken?.name ||
            targetActor?.name ||
            "Unbekanntes Ziel";

        let erfolgreich = false;

        if (
            hatNurtisSchale(casterActor) &&
            targetActor &&
            istErwacht(targetActor)
        ) {
            try {
                erfolgreich =
                    await wendeEffektAn({
                        casterActor,
                        targetActor,
                        qs
                    });
            } catch (error) {
                console.error(
                    "Milch der Reinigung: Effektanlage fehlgeschlagen.",
                    {
                        casterActor,
                        targetActor,
                        daten,
                        error
                    }
                );
            }
        }

        await DSK_FW.GabenUI
            .AnfrageKarteAktualisieren({
                messageId:
                    daten.messageId,

                gabenName:
                    vollerName,

                ahne,

                beschreibung:
                    daten.beschreibung ||
                    beschreibungFuer(
                        targetName,
                        qs
                    ),

                wirkender:
                    casterName,

                ziele: erfolgreich
                    ? [{
                        name:
                            targetName,
                        rolle:
                            "Empfänger der Reinigung"
                    }]
                    : [],

                misserfolge: erfolgreich
                    ? []
                    : [{
                        name:
                            targetName
                    }],

                dauerText,
                erfolgreich
            });

        if (erfolgreich) {
            ui.notifications.info(
                `Luna sagt 🌙: Bei ${targetName} kann ein Gift bis Giftstufe ${qs} neutralisiert werden.`
            );
        } else {
            ui.notifications.error(
                "Luna sagt 🌙: Milch der Reinigung konnte nicht angewendet werden!"
            );
        }

        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen =
            DSK_FW.GMAnfrage.Finden(
                flagKey
            );

        if (anfragen.length) {
            for (
                const anfrageActor
                of anfragen
            ) {
                const daten =
                    DSK_FW.GMAnfrage.Lesen(
                        anfrageActor,
                        flagKey
                    );

                if (!daten) {
                    continue;
                }

                if (
                    await verarbeiteAnfrage(
                        anfrageActor,
                        daten
                    )
                ) {
                    await DSK_FW.GMAnfrage
                        .Loeschen(
                            anfrageActor,
                            flagKey
                        );
                }
            }

            return;
        }
    }

    // +++ 7 - WIRKENDER +++++++++++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag(
                        "world",
                        "letzteGabenQS"
                    ) !== undefined
                ) ||
            game.actors.find(actor =>
                actor.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Kein Wirkender gefunden!"
        );
    }

    if (
        !game.user.isGM &&
        !casterActor.isOwner
    ) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken =
        DSK_FW.Token.Finde(
            casterActor
        );

    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
        );
    }

    const casterName =
        DSK_FW.ResolveTokenName(
            casterActor
        );

    // +++ 8 - NURTIS SCHALE PRÜFEN ++++++++++++++++++++++++++++

    if (!hatNurtisSchale(casterActor)) {
        await DSK_FW.GabenUI
            .AnfrageKarteErstellen({
                gabenName:
                    vollerName,

                ahne,

                beschreibung:
                    `Die Gabe schlägt fehl, weil kein durch ` +
                    `<b>Nurtis Schale</b> geweihtes Behältnis vorhanden ist.`,

                wirkender:
                    casterName,

                ziele: [],

                misserfolge: [{
                    name:
                        casterName
                }],

                dauerText:
                    "Keine Wirkung",

                gmBereich:
                    false,

                angewendet:
                    true,

                erfolgreich:
                    false,

                anfragenderUserId:
                    game.user.id
            });

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    // +++ 9 - QS ERMITTELN ++++++++++++++++++++++++++++++++++++

    const qs =
        DSK_FW.QS.Ermitteln({
            actor:
                casterActor,

            gabenName,

            suchbegriffe: [
                "Milch der Reinigung Probe",
                "Milch der Reinigung"
            ],

            testDataObj:
                typeof testData !==
                "undefined"
                    ? testData
                    : null,

            fallback:
                0,

            protokollieren:
                true
        });

    if (qs <= 0) {
        await DSK_FW.GabenUI
            .AnfrageKarteErstellen({
                gabenName:
                    vollerName,

                ahne,

                beschreibung:
                    "Die reinigende Milch konnte nicht verzaubert werden.",

                wirkender:
                    casterName,

                ziele: [],

                misserfolge: [{
                    name:
                        casterName
                }],

                dauerText:
                    "Keine Wirkung",

                gmBereich:
                    false,

                angewendet:
                    true,

                erfolgreich:
                    false,

                anfragenderUserId:
                    game.user.id
            });

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    // +++ 10 - GENAU EIN ZIEL PRÜFEN ++++++++++++++++++++++++++

    const targets =
        Array.from(
            game.user.targets || []
        );

    if (targets.length !== 1) {
        await raeumeQSAuf(
            casterActor
        );

        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle genau einen Empfänger für Milch der Reinigung!"
        );
    }

    const targetToken =
        targets[0];

    const targetActor =
        targetToken?.actor;

    const targetName =
        targetToken?.name ||
        targetActor?.name ||
        "Unbekanntes Ziel";

    if (
        !targetActor ||
        !istErwacht(targetActor)
    ) {
        await DSK_FW.GabenUI
            .AnfrageKarteErstellen({
                gabenName:
                    vollerName,

                ahne,

                beschreibung:
                    beschreibungFuer(
                        targetName,
                        qs
                    ),

                wirkender:
                    casterName,

                ziele: [],

                misserfolge: [{
                    name:
                        targetName
                }],

                dauerText,

                gmBereich:
                    false,

                angewendet:
                    true,

                erfolgreich:
                    false,

                anfragenderUserId:
                    game.user.id
            });

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    const targetDaten =
        DSK_FW.Target.Merken(
            targetToken
        );

    if (!targetDaten) {
        await raeumeQSAuf(
            casterActor
        );

        return ui.notifications.error(
            "Luna sagt 🌙: Der Empfänger konnte nicht gespeichert werden!"
        );
    }

    // +++ 11 - GEMEINSAME KARTE + GM-ANFRAGE ++++++++++++++++++

    const beschreibung =
        beschreibungFuer(
            targetName,
            qs
        );

    const gmLink =
        DSK_FW.GabenUI.GMMakroButton(
            macroUuid,
            "Effekt anwenden",
            "Das Makro muss durch die Spielleitung ausgeführt werden."
        );

    const nachricht =
        await DSK_FW.GabenUI
            .AnfrageKarteErstellen({
                gabenName:
                    vollerName,

                ahne,

                beschreibung,

                wirkender:
                    casterName,

                ziele: [{
                    name:
                        targetName,

                    rolle:
                        "Empfänger der Reinigung"
                }],

                misserfolge: [],

                dauerText,
                gmLink,

                gmBereich:
                    !game.user.isGM,

                anfragenderUserId:
                    game.user.id
            });

    if (!nachricht) {
        await raeumeQSAuf(
            casterActor
        );

        return ui.notifications.error(
            "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
        );
    }

    const anfrageDaten = {
        casterUuid:
            casterActor.uuid,

        casterName,

        casterTokenId:
            casterToken.id,

        casterTokenUuid:
            casterToken.document?.uuid ||
            casterToken.uuid ||
            null,

        target:
            targetDaten,

        qs,
        beschreibung,

        sceneId:
            canvas.scene?.id ||
            null,

        requestedByUserId:
            game.user.id,

        messageId:
            nachricht.id,

        macroUuid,
        erstellt:
            Date.now()
    };

    // +++ 12 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(
            casterActor,
            anfrageDaten
        );

        await raeumeQSAuf(
            casterActor
        );

        return;
    }

    await DSK_FW.GMAnfrage.Speichern(
        casterActor,
        flagKey,
        anfrageDaten
    );

    await raeumeQSAuf(
        casterActor
    );

    ui.notifications.info(
        "Luna sagt 🌙: Milch der Reinigung wurde bei der Spielleitung zur Anwendung beantragt."
    );
}).call(this);
